const exemples = [
  {
    "nom": "Demande complète",
    "payload": {
      "id_demande": "DEMO-001",
      "email": "contact@atelier.example",
      "service": "Maintenance de site",
      "quantite": 1
    },
    "attendu": {
      "statut": "a_valider",
      "nouveaux_brouillons": 1
    }
  },
  {
    "nom": "Rejeu du webhook",
    "payload": {
      "id_demande": "DEMO-001",
      "email": "contact@atelier.example",
      "service": "Maintenance de site",
      "quantite": 1
    },
    "attendu": {
      "statut": "doublon",
      "nouveaux_brouillons": 0
    }
  },
  {
    "nom": "Service manquant",
    "payload": {
      "id_demande": "DEMO-002",
      "email": "achats@exemple.example",
      "quantite": 2
    },
    "attendu": {
      "statut": "a_completer",
      "champ_a_corriger": "service",
      "nouveaux_brouillons": 0
    }
  },
  {
    "nom": "Espaces, casse et quantité en texte",
    "payload": {
      "id_demande": "DEMO-003",
      "email": "  INFO@AGENCE.EXAMPLE  ",
      "service": "Mise en page",
      "quantite": "3"
    },
    "attendu": {
      "statut": "a_valider",
      "email_normalise": "info@agence.example",
      "quantite_normalisee": 3,
      "nouveaux_brouillons": 1
    }
  },
  {
    "nom": "Adresse invalide",
    "payload": {
      "id_demande": "DEMO-004",
      "email": "info-sans-arobase.example",
      "service": "Intégration CRM",
      "quantite": 1
    },
    "attendu": {
      "statut": "a_completer",
      "champ_a_corriger": "email",
      "nouveaux_brouillons": 0
    }
  },
  {
    "nom": "Quantité non positive",
    "payload": {
      "id_demande": "DEMO-005",
      "email": "hello@studio.example",
      "service": "Reporting",
      "quantite": 0
    },
    "attendu": {
      "statut": "a_completer",
      "champ_a_corriger": "quantite",
      "nouveaux_brouillons": 0
    }
  }
];
return exemples.map((exemple) => ({ json: exemple }));

const brouillons = new Map();

function texte(valeur) {
  return typeof valeur === 'string' ? valeur.trim() : '';
}

function entierPositif(valeur) {
  const nombre = typeof valeur === 'string' && /^\d+$/.test(valeur.trim())
    ? Number(valeur.trim()) : valeur;
  return Number.isSafeInteger(nombre) && nombre > 0 ? nombre : null;
}

function traiter(demande) {
  const id_demande = texte(demande.id_demande);
  const email = texte(demande.email).toLowerCase();
  const service = texte(demande.service);
  const quantite = entierPositif(demande.quantite);

  if (brouillons.has(id_demande)) {
    return { id_demande, statut: 'doublon', nouveaux_brouillons: 0 };
  }

  const champs_a_corriger = [];
  if (!id_demande) champs_a_corriger.push('id_demande');
  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) champs_a_corriger.push('email');
  if (!service) champs_a_corriger.push('service');
  if (quantite === null) champs_a_corriger.push('quantite');

  if (champs_a_corriger.length) {
    return { id_demande, statut: 'a_completer', champs_a_corriger, nouveaux_brouillons: 0 };
  }

  const brouillon = { reference: id_demande, email, service, quantite, validation: 'en_attente' };
  brouillons.set(id_demande, brouillon);
  return {
    id_demande,
    statut: 'a_valider',
    email_normalise: email,
    quantite_normalisee: quantite,
    nouveaux_brouillons: 1,
    brouillon,
  };
}

return $input.all().map(({ json: exemple }) => ({
  json: { cas: exemple.nom, attendu: exemple.attendu, ...traiter(exemple.payload) },
}));

const resultats = $input.all().map(({ json }) => {
  const { attendu, ...obtenu } = json;
  const conforme = Object.entries(attendu).every(([champ, valeur]) => {
    if (champ === 'champ_a_corriger') return obtenu.champs_a_corriger?.includes(valeur);
    return obtenu[champ] === valeur;
  });
  if (!conforme) throw new Error('Résultat inattendu : ' + obtenu.cas);
  return { ...obtenu, conforme };
});

return [{ json: {
  cas_reussis: resultats.length,
  brouillons_a_valider: resultats.flatMap((cas) => cas.brouillon ? [cas.brouillon] : []),
  demandes_a_completer: resultats.filter((cas) => cas.statut === 'a_completer').length,
  doublons_ecartes: resultats.filter((cas) => cas.statut === 'doublon').length,
  resultats,
} }];
